// Verify the HMAC signature LendLoop (Convex) puts on every webhook.
// Signed string: "<x-lendloop-timestamp>.<raw body>". Rejects stale timestamps (replay window 5 min).
const crypto = require('crypto');
const secret = $env.LENDLOOP_TO_N8N_SECRET;
if (!secret) throw new Error('LENDLOOP_TO_N8N_SECRET is not configured');
const TOLERANCE_MS = 5 * 60 * 1000;

const item = $input.first();
const headers = item.json.headers || {};

// Prefer the exact raw bytes; fall back to re-serializing the parsed body
// (identical for the compact JSON that Convex sends).
let raw;
if (item.binary && item.binary.data) {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} else {
  raw = JSON.stringify(item.json.body);
}

const reject = (reason) => [{ json: { valid: false, reason } }];
const ts = headers['x-lendloop-timestamp'];
const sig = String(headers['x-lendloop-signature'] || '').trim().toLowerCase();
if (!ts || !sig) return reject('missing_headers');
if (!Number.isFinite(Number(ts)) || Math.abs(Date.now() - Number(ts)) > TOLERANCE_MS) return reject('stale_timestamp');

const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(ts + '.' + raw).digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(sig);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return reject('bad_signature');

let event;
try {
  event = JSON.parse(raw);
} catch (e) {
  return reject('invalid_json');
}
return [{ json: { valid: true, event } }];

// Build the email request for the configured provider (no secrets here: Brevo's
// API key lives in the "LendLoop Mail API" header-auth credential).
//  - LENDLOOP_MAIL_API=brevo -> Brevo transactional API over HTTPS (production)
//  - otherwise                -> Mailpit's send API (local docker-compose)
function mailRequest(to, subject, text) {
  const from = String($env.LENDLOOP_MAIL_FROM || 'LendLoop <no-reply@lendloop.local>');
  const m = from.match(/^\s*(.*?)\s*<([^>]+)>\s*$/);
  const sender = m ? { name: m[1] || 'LendLoop', email: m[2].trim() } : { name: 'LendLoop', email: from.trim() };
  if ($env.LENDLOOP_MAIL_API === 'brevo') {
    return {
      url: 'https://api.brevo.com/v3/smtp/email',
      body: { sender, to: [{ email: to }], subject, textContent: text },
    };
  }
  return {
    url: $env.LENDLOOP_MAILPIT_URL || 'http://mailpit:8025/api/v1/send',
    body: { From: { Email: sender.email, Name: sender.name }, To: [{ Email: to }], Subject: subject, Text: text },
  };
}

// Turn a LendLoop loan event into a short, friendly email.
// Uses only the fields Convex sent: recipient email + first name, the other
// party's first name, tool name and dates.
const e = $json.event;
const appUrl = $env.LENDLOOP_APP_URL || 'http://localhost:3000';
const fmt = (d) => new Date(d + 'T00:00:00Z').toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' });
const dates = e.loan.startDate === e.loan.endDate ? fmt(e.loan.startDate) : fmt(e.loan.startDate) + ' – ' + fmt(e.loan.endDate);
const tool = e.loan.toolName;
const other = e.counterpartFirstName;

const templates = {
  request_created: [`${other} would like to borrow your ${tool}`, `${other} asked to borrow your ${tool} for ${dates}.\n\nApprove or decline: ${appUrl}/incoming`],
  request_approved: [`${other} approved your request for the ${tool}`, `Good news! ${other} approved your request to borrow the ${tool} for ${dates}.\n\nSee pickup details: ${appUrl}/requests`],
  request_declined: [`Your request for the ${tool} was declined`, `Your request to borrow the ${tool} for ${dates} wasn't approved this time.\n\nFind something else: ${appUrl}/tools`],
  request_cancelled: [`${other} cancelled their request for your ${tool}`, `${other} cancelled their request to borrow your ${tool} for ${dates}. No action needed.`],
  loan_returned: [`Thanks for returning the ${tool}`, `${other} marked the ${tool} as returned. Thanks for being a good neighbor!`],
  listing_removed: [`The ${tool} is no longer available`, `The listing for the ${tool} was removed, so your request for ${dates} has been cancelled.\n\nBrowse other tools: ${appUrl}/tools`],
};
const t = templates[e.type];
if (!t) throw new Error('Unknown LendLoop event type: ' + e.type);

const to = e.recipient.email;
const subject = '[LendLoop] ' + t[0];
const text = 'Hi ' + e.recipient.firstName + ',\n\n' + t[1] + '\n\n— LendLoop';
return [{ json: { eventId: e.eventId, to, subject, text, mail: mailRequest(to, subject, text) } }];

const { eventId } = $('Compose message').first().json;
const err = $json.error;
const message = String((err && err.message) || err || 'Email delivery failed').slice(0, 300);
return [{ json: { payload: { eventId, status: 'failed', error: message, executionId: String($execution.id) } } }];

// Sign each outgoing payload for LendLoop (HMAC-SHA256 over "<timestamp>.<body>").
// The secret comes from the n8n environment, never from the workflow JSON.
const crypto = require('crypto');
const secret = $env.N8N_TO_LENDLOOP_SECRET;
if (!secret) throw new Error('N8N_TO_LENDLOOP_SECRET is not configured');

return $input.all().map((item) => {
  const body = JSON.stringify(item.json.payload);
  const timestamp = String(Date.now());
  const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');
  return { json: { body, timestamp, signature }, pairedItem: item.pairedItem };
});
